fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Number of rows and columns in the input matrix
    let n_rows = arr.len();
    let n_cols = arr[0].len();

    // Build the transpose: output has n_cols rows, each of length n_rows.
    (0..n_cols)
        .map(|j| {
            let mut new_row = Vec::with_capacity(n_rows);
            for i in 0..n_rows {
                // arr[i][j] is Copy (i8), so this just copies the value
                new_row.push(arr[i][j]);
            }
            new_row
        })
        .collect()
}

