        let m = vec![
            vec![1, 2, 3],
            vec![4, 5, 6],
            vec![7, 8, 9],
        ];
        let t = transpose(m);
        assert_eq!(
            t,
            vec![
                vec![1, 4, 7],
                vec![2, 5, 8],
                vec![3, 6, 9],
            ]
        );
